export const headings=['QP','HDA','HPP','EXAME','EXAMES','HD','CONDUTA'];
export function evolution(p){return headings.map(k=>`# ${k}\n${(p[k]?.trim()||'NA').toLocaleUpperCase('pt-BR')}`).join('\n\n')+(p.events.length?'\n\n'+p.events.map(e=>`# EM TEMPO · ${new Date(e.at).toLocaleString('pt-BR')}\n${e.text.toLocaleUpperCase('pt-BR')}`).join('\n\n'):'');}
export function evaluate(s,all){const a=Date.parse(s.start),b=Date.parse(s.end);if(!Number.isFinite(a)||!Number.isFinite(b)||b<=a)return {ok:false,reason:'Horário inválido'};if(a<=Date.now())return {ok:false,reason:'Plantão já iniciado'};if(s.role==='cardio')return {ok:false,reason:'Enfermaria de cardiologia bloqueada'};if(s.role==='reavaliador')return {ok:false,reason:'Função de reavaliador exige habilitação específica'};if(!['ps','extra'].includes(s.role))return {ok:false,reason:'Função não autorizada'};if(all.some(x=>x.id!==s.id&&x.status==='confirmed'&&a<Date.parse(x.end)&&b>Date.parse(x.start)))return {ok:false,reason:'Conflito com plantão confirmado'};return {ok:true,reason:s.role==='extra'?'Extra elegível, inclusive segunda de dia':'Elegível para sua revisão'};}
